def _atomic_write(path: str, text: str) -> None:
    """Write to a temp file in the same folder, then replace, so readers never see a partial file."""
    tmp = f"{path}.tmp-{os.getpid()}-{random.randint(0, 1_000_000)}"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(text)
    os.replace(tmp, path)


def write_deliverables(results: Dict[str, Dict[str, Any]], out_dir: str = OUTPUT_DIR) -> Dict[str, Any]:
    extractions_path = os.path.join(out_dir, "extractions.jsonl")
    queue_path = os.path.join(out_dir, "queue.json")
    records = [{k: results[d].get(k) for k in RECORD_FIELDS} for d in sorted(results)]
    _atomic_write(extractions_path, "".join(json.dumps(r, ensure_ascii=False) + "\n" for r in records))

    items = []
    for r in records:
        ex = r["extraction"] or {}
        items.append({
            "document_id": r["document_id"], "source_sha256": r["source_sha256"],
            "request_id": ex.get("request_id"), "kind": ex.get("kind"), "requester": ex.get("requester"),
            "team": ex.get("team"), "system": ex.get("system"), "environment": ex.get("environment"),
            "permission": ex.get("permission"), "start_date": ex.get("start_date"), "end_date": ex.get("end_date"),
            "manager": ex.get("manager"), "status": r["status"], "owner": r["owner"],
            "next_action": r["next_action"], "reasons": r["routing_reasons"], "issues": ex.get("issues", []),
            "error": r["error"], "response_source": r["response_source"],
            "last_success": r["last_success"],
            "retry_command": f'retry_failed(["{r["document_id"]}"])' if r["error"] else None,
        })
    summary = {}
    for it in items:
        key = f"{it['owner']} / {it['next_action']}"
        summary[key] = summary.get(key, 0) + 1
    queue = {
        "generated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "extractions_file": os.path.basename(extractions_path),
        "model": MODEL_CONFIG["model"], "settings_fingerprint": SETTINGS_FINGERPRINT,
        "policy_version": POLICY_VERSION, "total": len(items), "summary": dict(sorted(summary.items())),
        "items": items,
    }
    _atomic_write(queue_path, json.dumps(queue, indent=2, ensure_ascii=False) + "\n")
    return queue

